 sh=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
 assert sh(src)==sh(dest)
 name=''.join(w.title() for w in filename.split('_'));player='AudioStreamPlayer' if category=='ambience' else 'AudioStreamPlayer2D';bus='Ambience' if category=='ambience' else 'Effects';scene=ROOT/f'scenes/audio/chapter_03/c3_audio_{filename}.tscn'
 scene.write_text(f'''[gd_scene load_steps=2 format=3]\n[ext_resource type="AudioStream" path="res://{dest.relative_to(ROOT)}" id="1"]\n[node name="{name}" type="{player}"]\nstream = ExtResource("1")\nbus = &"{bus}"\nvolume_db = {-8.0 if category=='ambience' else -6.0}\nautoplay = false\nmax_polyphony = {1 if category=='ambience' else 3}\nmetadata/official_id = "{official}"\nmetadata/source_asset_id = "{old}"\nmetadata/source_status = "Existing procedural prototype reused unchanged; hearing/listening and actual scene mix approval pending"\nmetadata/production_approved = false\n''')
