 rows.append(dict(official_id=official,source_asset_id=old,source_path=str(src.relative_to(ROOT)),source_metadata=str(meta.relative_to(ROOT)),source_sha256=sh(src),runtime_path=str(dest.relative_to(ROOT)),runtime_sha256=sh(dest),copied_bytes_unchanged=True,native_path=str(scene.relative_to(ROOT)),native_sha256=sh(scene),bus=bus,loop=category=='ambience',format=ext,volume_db=-8.0 if category=='ambience' else -6.0,semantic_mapping=reason,measurements=measurements,measurements_provenance='Copied from original source metadata; not a new loudness/listening measurement',source_kind='Pre-existing code-synthesized procedural prototype; no new audio generation',stage='native import/playback review pending',production_approved=False))
